\begin{definition}
\label{def:8-60-extra-4}



A linear map $A\colon\mathfrak g\to\mathfrak h$ is a \emph{Lie algebra
homomorphism} if
\[
A[X,Y]=[AX,AY].
\]
An invertible Lie algebra homomorphism is a \emph{Lie algebra isomorphism}.
\end{definition}

